from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents on one line's amount, rounded half-even.

    Call per line item and sum the results; never round an invoice total.
    `rate` should be a Decimal or str (e.g. "0.0825"); floats are rejected.
    """
    if isinstance(rate, float):
        raise TypeError("rate must be Decimal, str or int, not float")
    exact = Decimal(amount_cents) * Decimal(rate)
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))
